1	#!/usr/bin/env node
2	// Offline semantic validator for UiPath Maestro BPMN XML.
3	//
4	// Pipeline:
5	//   1. Parse the BPMN with bpmn-moddle using the UiPath extension descriptor
6	//      (same getModdle() + fromXML() pattern as PO.Frontend).
7	//   2. Reconstruct the PO.Frontend Node[]/Edge[]/CanvasState model (model.mjs).
8	//   3. Run ALL 19 PO.Frontend validation rules (rules.mjs) per diagram, plus a
9	//      whole-model variable-existence check.
10	//   4. (Optional) Run the Maestro-original connection-liveness ping via uip CLI.
11	//
12	// Prints `VALID` and exits 0 when there are no ERROR-severity findings.
13	// Otherwise lists every finding (rule code + message) and exits non-zero.
14	// WARNING-severity findings are printed but do not gate.
15	//
16	// Usage: node validate-bpmn.mjs <bpmn-file> [resources]
17	//   resources: comma-separated release names, or a numeric folder ID, for the
18	//              optional solution-resource liveness ping (requires uip CLI auth).
19	import BpmnModdle from "bpmn-moddle";
20	import sax from "sax";
21	import descriptor from "./uipath-moddle.v1.json" with { type: "json" };
22	import { readFileSync, existsSync } from "fs";
23	import { execFileSync } from "child_process";
24	import { buildModel, collectKnownVariableIds, allNodes, allEdges } from "./model.mjs";
25	import { validateDiagram, validateVariableExistence, validateVariableNotSet, SEVERITY } from "./rules.mjs";
26	
27	// Strict XML well-formedness check via sax's strict mode. Returns the first
28	// error message (with a line number) or null when the document is well-formed.
29	function strictXmlError(xml) {
30	  const parser = sax.parser(true, {});
31	  let error = null;
32	  parser.onerror = (e) => {
33	    if (!error) {
34	      const line = (parser.line ?? 0) + 1;
35	      error = `${e.message.split("\n")[0]} (near line ${line})`;
36	    }
37	  };
38	  try {
39	    parser.write(xml).close();
40	  } catch (e) {
41	    if (!error) error = String(e.message ?? e).split("\n")[0];
42	  }
43	  return error;
44	}
45	
46	// --- uip CLI resolution (cached) — used only for the liveness-ping extra. ---
47	let _uipBin;
48	function resolveUipBin() {
49	  if (_uipBin !== undefined) return _uipBin;
50	  const home = process.env.HOME || process.env.USERPROFILE || "";
51	  const candidates = ["uip", `${home}/.bun/bin/uip`, `${home}/.local/bin/uip`, "/usr/local/bin/uip"];
52	  for (const p of candidates) {
53	    try {
54	      if ((p.startsWith("/") || p.startsWith(home)) && !existsSync(p)) continue;
55	      execFileSync(p, ["--version"], { encoding: "utf8", timeout: 5000, stdio: "pipe" });
56	      _uipBin = p;
57	      return p;
58	    } catch {
59	      /* keep trying */
60	    }
61	  }
62	  _uipBin = null;
63	  return null;
64	}
65	
66	function pingConnections(resourceArg) {
67	  // Maestro-original extra: liveness-check bound IS connections. Best-effort;
68	  // a missing/unauthenticated CLI is reported as a NOTE, never a hard failure.
69	  const bin = resolveUipBin();
70	  if (!bin) return { note: "uip CLI not found; skipped connection liveness ping." };
71	  try {
72	    const args = ["is", "connections", "ping", "--output", "json"];
73	    if (/^\d+$/.test(resourceArg)) args.push("--folder", resourceArg);
74	    const out = execFileSync(bin, args, { encoding: "utf8", timeout: 30000, stdio: "pipe" });
75	    return { ok: true, raw: out.trim() };
76	  } catch (e) {
77	    return { note: `connection liveness ping unavailable: ${String(e.message || e).split("\n")[0]}` };
78	  }
79	}
